CREATE OR REPLACE PACKAGE jq_demo AS
  TYPE t_user IS RECORD (
    name VARCHAR2(4000),
    age NUMBER
  );
  TYPE t_text_list IS TABLE OF VARCHAR2(4000) INDEX BY PLS_INTEGER;
  TYPE t_User_list IS TABLE OF t_user INDEX BY PLS_INTEGER;
  FUNCTION adult_names(p_j IN JSON) RETURN t_text_list;
  FUNCTION first_names(p_j IN JSON) RETURN t_text_list;
  FUNCTION all_users(p_j IN JSON) RETURN t_User_list;
  FUNCTION working_age(p_j IN JSON) RETURN t_text_list;
END jq_demo;
