CREATE OR REPLACE PACKAGE BODY jq_demo AS

  FUNCTION adult_names(p_j IN JSON) RETURN t_text_list IS
    l_names t_text_list;
  BEGIN
    SELECT jt.v
      BULK COLLECT INTO l_names
      FROM JSON_TABLE(p_j, '$.users[*]'
    COLUMNS (v VARCHAR2(4000) PATH '$.name', f0 NUMBER PATH '$.age')) jt
  WHERE jt.f0 >= 18;
    RETURN l_names;
  END adult_names;

  FUNCTION first_names(p_j IN JSON) RETURN t_text_list IS
    l_names t_text_list;
  BEGIN
    SELECT jt.v
      BULK COLLECT INTO l_names
      FROM JSON_TABLE(p_j, '$[*]'
    COLUMNS (v VARCHAR2(4000) PATH '$.name')) jt;
    RETURN l_names;
  END first_names;

  FUNCTION all_users(p_j IN JSON) RETURN t_User_list IS
    l_users t_User_list;
  BEGIN
    SELECT jt.name, jt.age
      BULK COLLECT INTO l_users
      FROM JSON_TABLE(p_j, '$.users[*]'
    COLUMNS (name VARCHAR2(4000) PATH '$.name', age NUMBER PATH '$.age')) jt;
    RETURN l_users;
  END all_users;

  FUNCTION working_age(p_j IN JSON) RETURN t_text_list IS
    l_names t_text_list;
  BEGIN
    SELECT jt.v
      BULK COLLECT INTO l_names
      FROM JSON_TABLE(p_j, '$.users[*]'
    COLUMNS (v VARCHAR2(4000) PATH '$.name', f0 NUMBER PATH '$.age')) jt
  WHERE jt.f0 >= 18 AND jt.f0 <= 65;
    RETURN l_names;
  END working_age;
END jq_demo;
